static struct cmd_obj * cmd_hdl_filter ( struct _adapter * padapter , struct cmd_obj * pcmd ) { struct cmd_obj * pcmd_r ; if ( ! pcmd ) { return pcmd ; } pcmd_r = NULL ; switch ( pcmd -> cmdcode ) { case GEN_CMD_CODE ( _Read_BBREG ) : read_bbreg_hdl ( padapter , ( u8 * ) pcmd ) ; break ; case GEN_CMD_CODE ( _Write_BBREG ) : write_bbreg_hdl ( padapter , ( u8 * ) pcmd ) ; break ; case GEN_CMD_CODE ( _Read_RFREG ) : read_rfreg_hdl ( padapter , ( u8 * ) pcmd ) ; break ; case GEN_CMD_CODE ( _Write_RFREG ) : write_rfreg_hdl ( padapter , ( u8 * ) pcmd ) ; break ; case GEN_CMD_CODE ( _SetUsbSuspend ) : sys_suspend_hdl ( padapter , ( u8 * ) pcmd ) ; break ; case GEN_CMD_CODE ( _JoinBss ) : r8712_joinbss_reset ( padapter ) ; if ( padapter -> pwrctrlpriv . pwr_mode > PS_MODE_ACTIVE ) { padapter -> pwrctrlpriv . pwr_mode = PS_MODE_ACTIVE ; mutex_lock ( & padapter -> pwrctrlpriv . mutex_lock ) ; r8712_set_rpwm ( padapter , PS_STATE_S4 ) ; mutex_unlock ( & padapter -> pwrctrlpriv . mutex_lock ) ; } pcmd_r = pcmd ; break ; case _DRV_INT_CMD_ : r871x_internal_cmd_hdl ( padapter , pcmd -> parmbuf ) ; pcmd_r = NULL ; break ; default : pcmd_r = pcmd ; break ; } return pcmd_r ; } 